"""Coval dashboard URL helpers."""

from __future__ import annotations

COVAL_WORKSPACE_RUNS_BASE = "https://app.coval.dev/rasa/workspace/default/runs"


def coval_run_results_url(run_id: str, simulation_id: str) -> str:
    """Return the Coval UI URL for one simulation result inside a run."""
    return f"{COVAL_WORKSPACE_RUNS_BASE}/{run_id}/results/{simulation_id}"
